// Direct Syscall Invocation (e.g., Linux/x86_64)
// Transition to kernel mode (TRAP)
#define SYS_write 1
#define STDOUT_FD 1

const char msg[] = "Syscall!\n";
long bytes_written;

bytes_written = syscall(SYS_write,
                        STDOUT_FD,
                        msg,
                        sizeof(msg) - 1);


// Signal Handler (Exceptional Control Flow)
void sig_handler(int sig) {
    if (sig == SIGSEGV) {
        // Kernel sent a signal due to invalid access
        exit(1);
    }
}

struct sigaction sa;
sa.sa_handler = sig_handler;
sigemptyset(&sa.sa_mask);
sigaction(SIGSEGV, &sa, NULL);


// Syscall Error Handling and EINTR check
int fd = open("file.txt", O_RDONLY);

if (fd == -1) {
    // Check global errno variable
    if (errno == EACCES) {
        // Permission denied
    }
    return;
}

// Handling interruption by signals (ECF interaction)
ssize_t n = read(fd, buffer, 1024);
if (n == -1 && errno == EINTR) {
    // System call restarted or must be manually retried
}
